  {"id":2,"codigo":"COMPUTO","nombre":"Cómputo","tipo":"interna","recibe_pases":true,"activa":true,"orden":2},
  {"id":3,"codigo":"LIQUIDACION","nombre":"Liquidación","tipo":"interna","recibe_pases":true,"activa":true,"orden":3},
  {"id":4,"codigo":"LEGAL","nombre":"Asesoría Legal","tipo":"interna","recibe_pases":true,"activa":true,"orden":4},
  {"id":5,"codigo":"ADMINISTRATIVO","nombre":"Administrativo","tipo":"interna","recibe_pases":true,"activa":true,"orden":5},
  {"id":6,"codigo":"TRIBUTARIO","nombre":"Departamento Tributario / Notificación","tipo":"interna","recibe_pases":true,"activa":true,"orden":6},
  {"id":7,"codigo":"DIRECCION","nombre":"Dirección","tipo":"interna","recibe_pases":false,"activa":true,"orden":7},
  {"id":8,"codigo":"DIM","nombre":"Dirección de Ingresos Municipales (DIM)","tipo":"externa","recibe_pases":true,"activa":true,"orden":8},
  {"id":9,"codigo":"CEM_OESTE","nombre":"Cementerio del Oeste","tipo":"externa","recibe_pases":true,"activa":true,"orden":9},
  {"id":10,"codigo":"CEM_NORTE","nombre":"Cementerio del Norte","tipo":"externa","recibe_pases":true,"activa":true,"orden":10},
  {"id":11,"codigo":"CEM_JARDIN_NORTE","nombre":"Cementerio Jardín Norte","tipo":"externa","recibe_pases":true,"activa":true,"orden":11}
]$semilla$::jsonb) AS d
ON CONFLICT DO NOTHING;
SELECT setval(pg_get_serial_sequence('public.areas', 'id'), coalesce(max("id"), 1), max("id") IS NOT NULL) FROM public.areas;

