]$semilla$::jsonb) AS d
ON CONFLICT DO NOTHING;

UPDATE public.plantillas p
   SET estado = d.estado, publicado_por = d.publicado_por, publicado_en = now()
  FROM jsonb_populate_recordset(NULL::public.plantillas, $semilla$[
  {"id":1,"estado":"publicada","publicado_por":1},
  {"id":2,"estado":"publicada","publicado_por":1},
  {"id":3,"estado":"publicada","publicado_por":1},
  {"id":4,"estado":"publicada","publicado_por":1},
  {"id":5,"estado":"publicada","publicado_por":1},
  {"id":6,"estado":"publicada","publicado_por":1}
]$semilla$::jsonb) AS d
 WHERE p.id = d.id AND p.estado = 'borrador' AND d.estado <> 'borrador';
SELECT setval(pg_get_serial_sequence('public.plantillas', 'id'), coalesce(max("id"), 1), max("id") IS NOT NULL) FROM public.plantillas;

RESET ROLE;
REVOKE cementeria_owner FROM postgres;
